// Definition for a binary tree node.
class Node {
    int data;
    Node left;
    Node right;
    Node(int data) { this.data = data; }
}

public void levelOrder(Node root) {
    if (root == null) return;
    Queue<Node> queue = new LinkedList<>();
    queue.offer(root);
    while (!queue.isEmpty()) {
        Node node = queue.poll();             // dequeue front (FIFO)
        System.out.print(node.data + " ");    // visit
        if (node.left != null) queue.offer(node.left);   // left first
        if (node.right != null) queue.offer(node.right);  // then right
    }
}

