from collections import deque

# Definition for a binary tree node.
class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def levelOrder(root: Node) -> None:
    if root is None:
        return
    queue = deque([root])
    while queue:
        node = queue.popleft()            # dequeue front (FIFO)
        print(node.data, end=' ')         # visit
        if node.left is not None:
            queue.append(node.left)       # left first
        if node.right is not None:
            queue.append(node.right)      # then right

